// Safely attempt to get the staff ID by checking nodes independently
let staffId = null;
let isManuallyCorrected = false; // New flag to track if this was manually corrected

// Attempt 1: 'clean data' node
try {
  const cleanDataNode = $('clean data').first();
  if (cleanDataNode && cleanDataNode.json.staff_id) {
    staffId = cleanDataNode.json.staff_id;
  }
} catch (error) {
  // Node didn't run or data is missing, move on
}

// Attempt 2: 'SAST image from phone' node
if (!staffId) {
  try {
    const phoneNode = $('SAST image from phone').first();
    if (phoneNode && phoneNode.json.body && phoneNode.json.body.user_id) {
      staffId = phoneNode.json.body.user_id;
    }
  } catch (error) {
    // Node didn't run or data is missing
  }
}

// Attempt 3: 'sast-manual-correction' node
try {
  const manualNode = $('sast-manual-correction').first();
  if (manualNode) {
    // If this node executed without throwing an error, we know it's a manual correction!
    isManuallyCorrected = true; 

    // Check for the user_id in the manual correction payload if we don't have a staffId yet
    if (!staffId && manualNode.json.body && manualNode.json.body.user_id) {
      staffId = manualNode.json.body.user_id;
    }
  }
} catch (error) {
  // Node didn't run, meaning this is an automated run
}

// Map the raw data and include the new database flags
const rawData = $input.all().map(item => {
  const r = item.json;
  return {
    json: {
      instructor_ID: r['instructor_ID'] || null,
      subject_id: r['true_subject_id'] || null,
      term_id: r['current_term_id'] || null,
      student_id: r['Student ID'] || null,
      instructor: r['Instructor/Professor'] || null,

      m1: Number(r['M1']) || null,
      m2: Number(r['M2']) || null,
      m3: Number(r['M3']) || null,
      m4: Number(r['M4']) || null,
      m5: Number(r['M5']) || null,
      m6: Number(r['M6']) || null,
      m7: Number(r['M7']) || null,
      m8: Number(r['M8']) || null,
      m9: Number(r['M9']) || null,
      m10: Number(r['M10']) || null,

      p1: Number(r['P1']) || null,
      p2: Number(r['P2']) || null,
      p3: Number(r['P3']) || null,
      p4: Number(r['P4']) || null,
      p5: Number(r['P5']) || null,
      p6: Number(r['P6']) || null,
      p7: Number(r['P7']) || null,
      p8: Number(r['P8']) || null,
      p9: Number(r['P9']) || null,
      p10: Number(r['P10']) || null,

      Remarks_and_Suggestions: String(r['Remarks & Suggestions'] ?? '').trim() || null,

      submitted_date: r['Date'] ? new Date(r['Date']).toISOString().split('T')[0] : null,

      sao_staff_id: staffId,

      // ADDED: Map to the columns shown in your Supabase screenshot
      manually_corrected: isManuallyCorrected,
      validation_status: isManuallyCorrected ? 'corrected' : 'auto'
    }
  };
});

const uniqueData = [];
const seen = new Set();

// Loop backwards to keep the newest submission and discard older duplicates
for (let i = rawData.length - 1; i >= 0; i--) {
  const item = rawData[i];
  const j = item.json;

  // The magic fingerprint checking Student + Instructor + Subject + Term
  const uniqueKey = `${j.student_id}_${j.instructor_ID}_${j.subject_id}_${j.term_id}`;

  if (!seen.has(uniqueKey)) {
    seen.add(uniqueKey);
    uniqueData.push(item);
  }
}

return uniqueData.reverse();

// Grab ALL 205 items from the If node
const allItems = $('If').all();
const uniquePairs = {};

// Loop through all of them and find every unique Instructor + Term combo
for (const item of allItems) {
  const instId = item.json.instructor_ID;
  const termId = item.json.current_term_id;

  if (instId && termId) {
    uniquePairs[`${instId}_${termId}`] = {
      instructor_id: instId,
      term_id: termId
    };
  }
}

// Return the full list of unique instructors so Postgres updates ALL of them
return Object.values(uniquePairs).map(pair => ({ json: pair }));

const items = $input.all();

return items.map(item => {
  // n8n Webhook data is usually inside item.json.body
  const payload = item.json.body || item.json;

  const staffId = payload.user_id;
  const googleLink = payload.link;
  let sheetId = '';

  if (googleLink && typeof googleLink === 'string') {
    const match = googleLink.match(/\/d\/(.*?)(\/|$)/);
    if (match && match[1]) {
      sheetId = match[1];
    }
  }

  return {
    json: {
      staff_id: staffId,
      google_link: googleLink,
      sheetId: sheetId,  // Changed this so the Google Node recognizes it automatically!
      import_type: payload.type,
      sync_time: payload.timestamp
    }
  };
});

// Mode: Run Once for Each Item
const base64Data = $input.item.json.body.image;
const taskId     = $input.item.json.body.task_id;
const userId     = $input.item.json.body.user_id;
const timestamp  = $input.item.json.body.timestamp;
const termId     = $input.item.json.body.term_id;      // ← ADD
const filename   = $input.item.json.body.filename;     // ← ADD
const paperSize  = $input.item.json.body.paper_size;   // ← ADD

if (!base64Data) {
  throw new Error('No image data in request body');
}

const cleanBase64 = base64Data.includes(',')
  ? base64Data.split(',')[1]
  : base64Data;

const buffer     = Buffer.from(cleanBase64, 'base64');
const binaryData = await this.helpers.prepareBinaryData(
  buffer,
  `${taskId}.jpg`,
  'image/jpeg'
);

return {
  binary: { data: binaryData },
  json: {
    user_id    : userId,
    term_id    : termId,      // ← ADD
    task_id    : taskId,
    filename   : filename,    // ← ADD
    paper_size : paperSize,   // ← ADD
    timestamp  : timestamp,
  }
};

const newItems = [];

// Generate today's date formatted as "Month DD, YYYY" specifically in Philippine Time
const todayFormatted = new Date().toLocaleDateString('en-US', { 
  timeZone: 'Asia/Manila',
  year: 'numeric', 
  month: 'long', 
  day: 'numeric' 
});

// 1. Fetch the flattened scores (m1-m10, p1-p10) from the previous formatting node
const formattedResults = $('2. Format Final Results').first().json;

// 2. Fetch the OCR data (student_id, date) from the "separate it" node
const separateData = $('separate it').first().json;

for (const item of $input.all()) {
  const data = item.json; // This is the input from 'Set Status - Auto'
  const result = {};

  // 1. Map IDs
  result["instructor_ID"] = $('get instructor id1').first().json.instructor_id || null;
  result["true_subject_id"] = $('get subject id1').first().json.subject_id || null;
  result["current_term_id"] = data.current_term_id || null;

  // 2. Map standard text fields to your target schema
  result["Student ID"] =  separateData.student_id || "";

  // Safely combine first name and last name with a space in between
  const firstName = $('get instructor id1').first().json.first_name || "";
  const lastName = $('get instructor id1').first().json.last_name || "";
  result["Instructor/Professor"] = `${firstName} ${lastName}`.trim();

  result["Subject Taught"] =  $('get subject id1').first().json.subject_name || "";

  // Handle ay_semester 
  result["AY/Semester"] = (data.academic_terms?.semester || "") + " " + (data.academic_terms?.academic_year || "");

  result["Remarks & Suggestions"] = $('separate it').first().json.remarks|| "";

  // Handle Date: Check if true, null, undefined, or empty string, then apply local date

  result["Date"] = todayFormatted;

  // 3. Map OMR Scores (Converts lowercase m1/p1 to uppercase M1/P1)
  for (let i = 1; i <= 10; i++) {
    result[`M${i}`] = formattedResults[`m${i}`] !== undefined ? formattedResults[`m${i}`] : 0;
    result[`P${i}`] = formattedResults[`p${i}`] !== undefined ? formattedResults[`p${i}`] : 0;
  }

  newItems.push({ json: result });
}

return newItems;

const newItems = [];

// 1. Target the correct node that contains the Python OMR API results
// Updated from 'separate it' to 'image to ocr and omr python'
const omrData = $('image to ocr and omr python').first().json;

// 2. Target the AI node for the cleaned remarks
const aiData = $('separate it').first().json.remarks;

for (const item of $input.all()) {
  const result = {};

  // ── 1. Map OMR scores → m1…m10 and p1…p10 ─────────────────────────────
  const mgmt = omrData.ratings?.management ?? [];
  const perf = omrData.ratings?.performance ?? [];

  for (let i = 0; i < 10; i++) {
    result[`m${i + 1}`] = (mgmt[i] && mgmt[i].detected) ? mgmt[i].score : 0;
    result[`p${i + 1}`] = (perf[i] && perf[i].detected) ? perf[i].score : 0;
  }

  // ── 2. Extract Summary Stats from OMR Data ───────────────────────────
  const s = omrData.summary ?? {};
  result.answered    = s.answered      ?? null;
  result.total_score = s.sum           ?? null;
  result.average     = s.average       ?? null;
  result.percent     = s.percent_score ?? null;

  // ── 3. Pipeline metadata ─────────────────────────────────────────────
  result.grid_source = omrData.grid_source ?? null;
  result.table_found = omrData.table_found ?? null;

  // ── 4. AI Cleaned Remarks ─────────────────────────────────────────────
  result.cleaned_remarks = $('separate it').first().json.remarks ?? "";

  newItems.push({ json: result });
}

return newItems;

