const groups = {};

// 1. Group data by Instructor AND Subject
for (const item of items) {
  const id = item.json.instructor_ID;
  const subjectId = item.json.true_subject_id || item.json.subject_id;
  if (!id || !subjectId) continue;

  const key = `${id}_${subjectId}`;

  if (!groups[key]) {
    groups[key] = {
      instructor_id: id,
      subject_id: subjectId,
      term_id: item.json.current_term_id ?? null,
      count: 0,
      totals: {
        p1: 0, p2: 0, p3: 0, p4: 0, p5: 0,
        p6: 0, p7: 0, p8: 0, p9: 0, p10: 0
      }
    };
  }

  groups[key].count++;
  for (let i = 1; i <= 10; i++) {
    const valKey = `P${i}`;
    const val = Number(item.json[valKey]);
    if (!isNaN(val)) {
      groups[key].totals[`p${i}`] += val;
    }
  }
}

// 2. Build output
const output = [];
for (const key in groups) {
  const data = groups[key];
  const means = {};
  const totalsOut = {};
  let sumMeans = 0;
  let grandTotal = 0;

  for (let i = 1; i <= 10; i++) {
    const total = data.totals[`p${i}`];
    const mean = total / data.count;
    totalsOut[`p${i}_total`] = total;
    means[`p${i}_mean`] = Number(mean.toFixed(2));  // ✅ 2 decimal places
    sumMeans += mean;
    grandTotal += total;
  }

  // ✅ FIX 1: renamed to snake_case to match Supabase column
  const overall_performance_mean = Number((grandTotal / (data.count * 10)).toFixed(2));
  const average_per_response_performance = Number((grandTotal / data.count).toFixed(2));

  output.push({
    json: {
      instructor_id: data.instructor_id,  // ✅ FIX 2: lowercase 'd'
      term_id: data.term_id,
      subject_id: data.subject_id,
      total_responses: data.count,
      ...totalsOut,
      grand_total: grandTotal,
      ...means,
      overall_performance_mean,            // ✅ FIX 1: correct column name
      average_per_response_performance
    }
  });
}

return output;

