const newItems = [];

// Generate today's date formatted as "Month DD, YYYY" specifically in Philippine Time
const todayFormatted = new Date().toLocaleDateString('en-US', { 
  timeZone: 'Asia/Manila',
  year: 'numeric', 
  month: 'long', 
  day: 'numeric' 
});

// Fetch term info from the initial Webhook node
const webhookData = $('Google LINK from phone').first().json.body;

// Get all items from the respective nodes to map them index-by-index (for all 149 rows)
const sheetItems = $('Get row(s) in sheet').all();
const instructorItems = $('get instructor id').all();
const subjectItems = $('get subject id').all();
const termItems = $('GET TERM BY ID').all(); 

for (let i = 0; i < sheetItems.length; i++) {
  // 1. Pull the data specific to THIS row (Index i)
  const data = sheetItems[i].json; // This is the Google Sheet row containing M1, P1, Student ID
  const instructorData = instructorItems[i] ? instructorItems[i].json : {};
  const subjectData = subjectItems[i] ? subjectItems[i].json : {};
  const termData = termItems[i] ? termItems[i].json : {};

  const result = {};

  // 2. Map IDs (using index i, avoiding .first() so it doesn't duplicate row 1)
  result["instructor_ID"] = instructorData.instructor_id || null;
  result["true_subject_id"] = subjectData.subject_id || null; 
  result["current_term_id"] = termData.current_term_id || webhookData.term_id || null;

  // 3. Map standard text fields
  result["Student ID"] = data["Student ID"] || data["student_id"] || "";

  // Combine first and last name 
  const firstName = instructorData.first_name || "";
  const lastName = instructorData.last_name || "";
  result["Instructor/Professor"] = `${firstName} ${lastName}`.trim();

  // Subject Taught (checks the database lookup first, then falls back to the sheet text)
  result["Subject Taught"] = subjectData.subject_name || data["Subject Taught"] || "";

  // Handle ay_semester from the webhook body
  result["AY/Semester"] = (webhookData.semester || "") + " " + (webhookData.academic_year || "");

  // Extract remarks from the sheet
  result["Remarks & Suggestions"] = data["Remarks & Suggestions"] || data["Remarks"] || "";

  // Handle Date
  if (data.Date === true || !data.Date || data.Date.toString().trim() === "") {
    result["Date"] = todayFormatted;
  } else {
    result["Date"] = data.Date;
  }

  // 4. Map Scores
  for (let j = 1; j <= 10; j++) {
    // Look for uppercase first, fallback to lowercase
    let mScore = data[`M${j}`] !== undefined ? data[`M${j}`] : data[`m${j}`];
    let pScore = data[`P${j}`] !== undefined ? data[`P${j}`] : data[`p${j}`];

    result[`M${j}`] = mScore !== undefined ? mScore : null;
    result[`P${j}`] = pScore !== undefined ? pScore : null;
  }

  newItems.push({ json: result });
}

return newItems;

// ============================================================
// GROUP NEW FEEDBACK BY INSTRUCTOR + TERM
// ============================================================

const grouped = new Map();

for (const item of items) {

  const data = item.json || {};

  const instructor_ID =
    String(data.instructor_ID ?? "").trim();

  const term_id =
    String(data.current_term_id ?? "").trim();

  const remark =
    String(
      data["Remarks & Suggestions"] ??
      data.remark ??
      ""
    ).trim();

  const subject_id =
    String(
      data.true_subject_id ??
      data.subject_id ??
      ""
    ).trim();

  // ----------------------------------------------------------
  // IMPORTANT:
  // Do NOT use student_id as source_response_id.
  // One student can submit multiple remarks.
  // ----------------------------------------------------------

  const source_response_id =
    String(
      data.response_id ??
      data.evaluation_id ??
      data.student_response_id ??
      ""
    ).trim();

  // ----------------------------------------------------------
  // VALIDATION
  // ----------------------------------------------------------

  if (!instructor_ID) continue;
  if (!term_id) continue;
  if (!remark) continue;

  if (remark.length < 2) continue;

  // ----------------------------------------------------------
  // GROUP
  // ----------------------------------------------------------

  const key =
    `${instructor_ID}::${term_id}`;

  if (!grouped.has(key)) {

    grouped.set(key, {
      instructor_ID,
