    subject_id:
      subject_id || null,

    source_response_id:
      source_response_id || null

  });

}

// ============================================================
// REMOVE DUPLICATES ONLY WHEN SOURCE RESPONSE ID EXISTS
// ============================================================

for (const group of grouped.values()) {

  const seen = new Set();

  group.remarks =
    group.remarks.filter(item => {

      // No source ID:
      // keep the remark.
      if (!item.source_response_id) {
        return true;
      }

      if (
        seen.has(
          item.source_response_id
        )
      ) {
        return false;
      }

      seen.add(
        item.source_response_id
      );

      return true;

    });

}

// ============================================================
// OUTPUT
