  String(
    original.instructor_ID ?? ""
  ).trim();

const termId =
  String(
    original.term_id ?? ""
  ).trim();

if (!instructorId) {
  throw new Error(
    "Missing instructor_ID."
  );
}

if (!termId) {
  throw new Error(
    "Missing term_id."
  );
}

// ============================================================
// CLEAN GEMINI RESPONSE
// ============================================================

let clean =
  String(aiResponse)
    .trim()
    .replace(
      /^```json\s*/i,
      ""
    )
    .replace(
      /^```\s*/i,
      ""
    )
    .replace(
      /\s*```$/i,
      ""
    )
    .trim();

const start =
  clean.indexOf("{");

const end =
  clean.lastIndexOf("}");

if (
  start === -1 ||
  end === -1 ||
  end <= start
) {
  throw new Error(
    "Gemini did not return valid JSON.\n\n" +
    clean
  );
}

clean =
  clean.substring(
    start,
    end + 1
  );

let result;

try {

  result =
    JSON.parse(clean);

