  throw new Error(
    "Gemini JSON parsing failed: " +
    error.message +
    "\n\nResponse:\n" +
    clean
  );

}

// ============================================================
// HELPERS
// ============================================================

const VALID_TONES = [
  "Positive",
  "Critical",
  "Neutral"
];

function normalizeTone(value) {

  if (
    typeof value === "string"
  ) {

    const tone =
      value.trim();

    if (
      VALID_TONES.includes(tone)
    ) {
      return tone;
    }

  }

  return null;
}

function cleanText(value) {

  if (
    value === null ||
    value === undefined
  ) {
    return "";
  }

  return String(value).trim();
}

