    cleanText(
      rawEvaluation.interpretation
    ),

  positives:
    cleanText(
      rawEvaluation.positives
    ),

  improvements:
    cleanText(
      rawEvaluation.improvements
    ),

  suggestion:
    cleanText(
      rawEvaluation.suggestion
    )

};

if (!evaluation.interpretation) {
  throw new Error(
    "Empty interpretation."
  );
}

if (!evaluation.positives) {
  throw new Error(
    "Empty positives."
  );
}

if (!evaluation.improvements) {
  throw new Error(
    "Empty improvements."
  );
}

if (!evaluation.suggestion) {
  throw new Error(
    "Empty suggestion."
  );
}

// ============================================================
// OVERALL TONE
// ============================================================

const overallTone =
  normalizeTone(
    result.overall_tone
  );

if (!overallTone) {
  throw new Error(
