const rawRemarkTones =
  Array.isArray(
    result.remark_tones
  )
    ? result.remark_tones
    : null;

if (!rawRemarkTones) {
  throw new Error(
    "Gemini did not return remark_tones."
  );
}

// Expected indexes
const expectedIndexes =
  feedback.map(
    item =>
      Number(item.index)
  );

const expectedSet =
  new Set(expectedIndexes);

const receivedMap =
  new Map();

