// ------------------------------------------------------------

for (
  const item of rawRemarkTones
) {

  const index =
    Number(item?.index);

  if (
    !Number.isInteger(index)
  ) {
    throw new Error(
      "Invalid remark index."
    );
  }

  if (
    !expectedSet.has(index)
  ) {
    throw new Error(
      `Unknown remark index: ${index}`
    );
  }

  if (
    receivedMap.has(index)
  ) {
    throw new Error(
      `Duplicate remark index: ${index}`
    );
  }

  const tone =
    normalizeTone(
      item?.tone
    );

  if (!tone) {
    throw new Error(
      `Invalid tone for remark ${index}.`
    );
  }

  receivedMap.set(
    index,
    tone
  );

}

// ------------------------------------------------------------
// Ensure EVERY feedback item has a tone
// ------------------------------------------------------------

for (
  const index of expectedIndexes
) {

  if (
    !receivedMap.has(index)
  ) {

    throw new Error(
      `Missing tone for remark ${index}.`
    );

  }

}

// ============================================================
